"""Small additive first-negative checkpoint; no emulator or evidence mutation."""
from pathlib import Path
import argparse,hashlib,json,shutil
from final_samus_hard_gallery_source_v1 import D,ROOT,SHA
from final_item_abilities_remaining731_run_v1 import verify_manifest
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
put=lambda p,z:p.write_text(json.dumps(z,indent=2)+'\n',encoding='utf-8')
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False)
 neg=D/'current3b112-samus-hard-gallery-negative-v1';ready=D/'current3b112-samus-hard-outline-ready-v2';native=D/'current3b112-samus-hard-gallery-ready-v2/native'
